function OverseaManageMerchantTalkingNode:InitNodeEnv()
    self.optionEnv = {}
    for i = 1, OptionCount do
        local optionNode = self["BtnOption"..i]
        if optionNode then
            local env = CfUtils.GetLuaScr(optionNode,OptionPath)
            if not isNull(env) then
                env:SetOptionCallBack(Bind(self,self.OnOptionCellClick))
                self.optionEnv[i] = env
            end
        end
    end

    if self.OverseaManageMerchantInfoDialog then
        local env = CfUtils.GetLuaScr(self.OverseaManageMerchantInfoDialog,"Game.MaidCoffee.MaidCoffeeCallOnUIDialog.OverseaManageMerchantInfoDialog")
        if env then
            self.sellEnv = env
        end
    end
end

