end

function OverseaManageMerchantTalkingNode:RefreshTopGoods()
    local goodIdVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 54)
    local itemGoodId = checkNumber(goodIdVo.num)

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 52)
    local costGoodId = checkNumber(vo.num)
    CfUtils.RefreshTopGoods({ itemGoodId,costGoodId})
end

function OverseaManageMerchantTalkingNode:GetChoicesIndex()
    return not isNull(self.choicesIndex) and self.choicesIndex or 0
end

function OverseaManageMerchantTalkingNode:RefreshUI(index)
    if index == 0 or isNull(self.storyData) or index > table.count(self.storyData) then
        --TODO 说明剧情结束了
        self:OnExitBtnClick()
        return
    end
    self.curIndex = index
    self.controller:SetExtraArgument(tostring(table.concat({self.curIndex,"_",self:GetChoicesIndex()})))
    local talkingVo = self:GetTalkingDataByIndex(index)
    self.talkingVo = talkingVo
    if isNull(talkingVo) then
        --TODO 说明剧情结束了
        self:OnExitBtnClick()
        return
    end

    self.GotoNext = nil

    if isNull(self._dialogCo) then
        self._dialogCo = {}
    end

    self._dialogCo[index] = cs_coroutine.start(function()
        self._endWait = true
        self:SetText(talkingVo)
        self:SetName(talkingVo)
        self:SetHeadIcon(talkingVo)

        local isChoices = table.count(talkingVo.choices) > 0
        if isChoices then
            KTool.SetActive(self.Option.gameObject,true)
            for i = 1, OptionCount do
                local data = talkingVo.choices[i]
                if not isNull(data) then
                    KTool.SetActive(self.optionEnv[i].controller.gameObject,true)
                    self.optionEnv[i]:RefreshOption(data,self:GetChoicesIndex())
                else
                    KTool.SetActive(self.optionEnv[i].controller.gameObject,false)
                end
            end
            self.choicesId = talkingVo.id
            KTool.SetActive(self.ScreenBtn.gameObject,false)
        else
            KTool.SetActive(self.ScreenBtn.gameObject,true)
            self:SetButtonClick(self.ScreenBtn,function()
                if self.BlockClick then
                    return
                end
                self.ScreenBtn.onClick:RemoveAllListeners()
                self.GotoNext = talkingVo.jumpId
                self._endWait = false
            end)
        end

        while self._endWait do
            coroutine.yield()
        end
        KTool.SetActive(self.ScreenBtn.gameObject, false)

        ---事件真正的结束
        if talkingVo.endFlag then
            self:OnExitBtnClick()
        else
            if self.GotoNext ~= nil then
                self:RefreshUI(self.GotoNext)
            end
        end
    end)
end

function OverseaManageMerchantTalkingNode:OnOptionCellClick(data)
    self.choicesData = data
    self.choicesIndex = self.choicesData.choiceIndex
    self.controller:SetExtraArgument(tostring(table.concat({self.curIndex,"_",self.choicesIndex})))
    KTool.SetActive(self.Option.gameObject,false)
    if data.choiceType == OptionType.Dialog then
        self.GotoNext = data.choiceJumpId
        self._endWait = false
    elseif data.choiceType == OptionType.SellGoods then
        self:EnterSell()
    else
        printError("不存在的选项类型 choiceType === %s 请检查 商人对话表",data.choiceType)
    end
end

function OverseaManageMerchantTalkingNode:EnterSell()
    self.sellEnv:RefreshShow()
end

